use crate::aap::caps::http_client;

/// The hosts this node's `HTTPClient` handle is scoped to. A request outside
/// this set would trap at the boundary, so such URLs are recorded as failures
/// here instead of being sent. One bad subscription then cannot fail the tick.
const ALLOWED_HOSTS: &[&str] = &[
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extract the host from an http(s) URL, or `None` if it is not one.
fn host_of(url: &str) -> Option<String> {
    let trimmed = url.trim();
    let lower = trimmed.to_ascii_lowercase();
    let rest = if lower.starts_with("https://") {
        &trimmed[8..]
    } else if lower.starts_with("http://") {
        &trimmed[7..]
    } else {
        return None;
    };

    // The authority ends at the first '/', '?' or '#'.
    let end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..end];

    // Drop any userinfo. The host follows the last '@'.
    let host_port = match authority.rfind('@') {
        Some(i) => &authority[i + 1..],
        None => authority,
    };

    // Drop any port.
    let host = match host_port.rfind(':') {
        Some(i) => &host_port[..i],
        None => host_port,
    };

    let host = host.trim_end_matches('.').to_ascii_lowercase();
    if host.is_empty() {
        None
    } else {
        Some(host)
    }
}

fn is_allowed(url: &str) -> bool {
    match host_of(url) {
        Some(h) => ALLOWED_HOSTS.iter().any(|a| *a == h),
        None => false,
    }
}

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();
        let mut seen: Vec<String> = Vec::new();

        for url in subscriptions.urls {
            let url = url.trim().to_string();
            if url.is_empty() {
                continue;
            }
            if seen.iter().any(|s| *s == url) {
                continue;
            }
            seen.push(url.clone());

            if !is_allowed(&url) {
                failures.push(FetchFailure {
                    url,
                    error: "host not in this node's HTTP allowlist".to_string(),
                });
                continue;
            }

            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
